import json
import sys

for i in range(480):
    print("INFO worker-%d processed batch %d in %dms" % (i % 8, i, 20 + (i * 37) % 180))
cfg = json.load(open("config.json"))
problems = []
if not isinstance(cfg.get("retries"), int) or not 1 <= cfg["retries"] <= 5:
    problems.append("ERROR missing config key: retries (expected integer between 1 and 5)")
for p in problems:
    print(p)
for i in range(120):
    print("INFO worker-%d shutting down, flushed %d records" % (i % 8, (i * 13) % 1000))
if problems:
    sys.exit(1)
print("OK service ready")

